from pathlib import Path
import shutil
R=Path(__file__).resolve().parents[1];h=R/'history/full-tour-first-pass';h.mkdir(parents=True,exist_ok=True)
for p in (R/'runtime/results').glob('campus16-*'):
 if 'social04' not in p.name:shutil.copy2(p,h/p.name)
p=R/'runtime16/harness.js';s=p.read_text();start=s.index('function record(name)');end=s.index('async function checkRenderedEffect',start)
s=s[:start]+'''function record(name){const videoStream=game.canvas.captureStream(24),audioStream=sound.getCaptureStream(),stream=new MediaStream([...videoStream.getVideoTracks(),...(audioStream?.getAudioTracks()??[])]),prefix=name+'-'+Date.now();let sequence=0,bytes=0,pending=Promise.resolve(),uploadError=null;const recorder=new MediaRecorder(stream,{mimeType:'video/webm;codecs=vp9,opus',videoBitsPerSecond:1600000});recorder.ondataavailable=e=>{if(!e.data.size)return;const index=sequence++;bytes+=e.data.size;pending=pending.then(async()=>{const value=await new Promise(r=>{const f=new FileReader;f.onload=()=>r(f.result.split(',')[1]);f.readAsDataURL(e.data)});await save(prefix+'-chunk-'+String(index).padStart(5,'0'),'report',{index,bytes:e.data.size,base64:value});}).catch(error=>{uploadError=error;});};report.captureStartTime=performance.now();recorder.start(2000);return async()=>{await new Promise(r=>{recorder.onstop=r;recorder.stop()});videoStream.getTracks().forEach(t=>t.stop());await pending;if(uploadError)throw uploadError;const manifest={bytes,type:'video/webm',chunkPrefix:prefix,chunks:sequence,method:'Unmodified MediaRecorder timeslice chunks, concatenate bytes in order; original timestamps retained.'};await save(name+'-recording-manifest','report',manifest);return manifest;};}
''' +s[end:]
s=s.replace("errors:[],completed:false", "errors:[],frameIntegrity:{checks:0,overlaps:0,dimensionErrors:0,cameraErrors:0},completed:false")
s=s.replace("if(running&&time-lastSample>=30)", "if(running){const q=report.frameIntegrity;q.checks++;q.overlaps+=Number(bodyOverlap());q.dimensionErrors+=Number(b.width!==16||b.height!==16||!b.immovable||this.greg.width!==32||this.greg.scaleX!==1||this.greg.scaleY!==1);const c=this.cameras.main;q.cameraErrors+=Number(c.zoom!==1||c.scrollX<0||c.scrollY<0||c.scrollX>3200-settings.width||c.scrollY>3072-settings.height);}if(running&&time-lastSample>=(socialCase?30:125))")
s=s.replace("assert('no overlap with permanent solid tiles',report.samples.every(s=>!s.overlap)", "assert('no overlap with permanent solid tiles',report.frameIntegrity.overlaps===0&&report.samples.every(s=>!s.overlap)")
s=s.replace("await pause(100);}report.video", "await save('continuous-campus16-progress','report',{lastGoal:leg.goal.id,assertions:report.assertions,checkpoints:report.checkpoints,frameIntegrity:report.frameIntegrity,errors:report.errors});await pause(100);}report.video")
